INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',9,NULL,'choice','{"stem":"你没听清对方的话,想请他再说一遍:","options":["I got angry.","Sorry, I couldn''t hear you — could you say that again?","It''s none of your business.","This is a private conversation."],"answer_index":1}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
